/**
 * Единый (движок-независимый) контракт данных виджета визуализации.
 *
 * Оба режима принимают одинаковый колоночный формат: общая временная шкала
 * + набор серий со значениями, выровненными по этой шкале. Какой движок
 * отрисует данные (gravity-charts или yagr), решает сам виджет по режиму.
 */

export type VisualizationMode = 'sales' | 'monitoring';

export interface TimeSeries {
    id: string;
    name: string;
    /** Значения, выровненные по `timeline`; `null` — разрыв в данных. */
    values: Array<number | null>;
}

export interface TimeSeriesSet {
    /** Временные метки в миллисекундах (Unix epoch), по возрастанию. */
    timeline: number[];
    series: TimeSeries[];
}

export interface VisualizationView {
    /** Подпись режима в переключателе. */
    label: string;
    /** Единица измерения значений (подпись оси Y и тултипа). */
    unit?: string;
    /** Количество знаков после запятой в подписях значений. */
    precision?: number;
    data: TimeSeriesSet;
}

export type VisualizationViews = Record<VisualizationMode, VisualizationView>;

export interface VisualizationWidgetRef {
    /** Перерисовать активный график под текущий размер контейнера. */
    reflow: () => void;
}
EOF
cat > chartkit.ts <<'EOF'
import {settings} from '@gravity-ui/chartkit';
import {GravityChartsPlugin} from '@gravity-ui/chartkit/gravity-charts';
import {YagrPlugin} from '@gravity-ui/chartkit/yagr';

/**
 * Регистрация движков в глобальном реестре ChartKit.
 *
 * Плагины содержат только `React.lazy`-рендереры: код `@gravity-ui/charts`
 * и `@gravity-ui/yagr` загружается отдельным чанком при первом показе
 * соответствующего режима, а не в основном бандле.
 */
settings.set({
    plugins: [GravityChartsPlugin, YagrPlugin],
    lang: 'ru',
});
EOF
cat > adapters.ts <<'EOF'
import type {ChartData, LineSeries} from '@gravity-ui/chartkit/gravity-charts';
import type {YagrWidgetData} from '@gravity-ui/chartkit/yagr';

import type {TimeSeriesSet, VisualizationView} from './types';

export function isEmptySet({timeline, series}: TimeSeriesSet): boolean {
    return timeline.length === 0 || series.length === 0;
}

function withUnit(unit?: string): string | undefined {
    return unit ? ` ${unit}` : undefined;
}

/** Режим «Продажи»: декларативный линейный график на `@gravity-ui/charts`. */
export function toSalesChartData(view: VisualizationView): ChartData {
    const {data, unit, precision = 0} = view;

    const series: LineSeries[] = data.series.map((s) => ({
        type: 'line',
        id: s.id,
        name: s.name,
        marker: {enabled: true},
        data: data.timeline.map((x, i) => ({x, y: s.values[i] ?? null})),
    }));

    return {
        xAxis: {type: 'datetime'},
        yAxis: [
            {
                title: unit ? {text: unit} : undefined,
                labels: {numberFormat: {precision}},
            },
        ],
        legend: {enabled: series.length > 1},
        tooltip: {
            valueFormat: {type: 'number', precision, postfix: withUnit(unit)},
        },
        series: {data: series},
    };
}

/** Режим «Мониторинг»: плотный временной ряд на canvas-движке `@gravity-ui/yagr`. */
export function toMonitoringYagrData(view: VisualizationView): YagrWidgetData {
    const {data, unit, precision = 1} = view;

    return {
        data: {
            timeline: data.timeline,
            graphs: data.series.map((s) => ({
                id: s.id,
                name: s.name,
                data: s.values,
            })),
        },
        libraryConfig: {
            chart: {
                series: {type: 'line', lineWidth: 1.5},
                select: {zoom: true},
                timeMultiplier: 1,
            },
            axes: {
                y: {
                    precision,
                    values: (_u, ticks) => ticks.map((t) => `${t}${withUnit(unit) ?? ''}`),
                },
            },
            legend: {show: data.series.length > 1, position: 'bottom'},
            tooltip: {
                precision,
                value: (v) => (v === null ? '—' : `${(v as number).toFixed(precision)}${withUnit(unit) ?? ''}`),
            },
        },
    };
}
EOF
